{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Rilzabrutinib, a covalent BTK inhibitor with an aminopyrimidine core, acrylamide-like warhead, high molecular weight and lipophilicity, had an absolute oral bioavailability below 5% in healthy subjects, directly supporting a low F prediction for the similarly large and lipophilic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "CC-292, a smaller and more polar covalent BTK inhibitor with an acrylamide and aminopyrimidine, showed excellent oral bioavailability in humans, providing contradictory evidence; however, its lower lipophilicity and smaller size limit transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "Afatinib, a covalent acrylamide inhibitor, has good oral bioavailability in humans, but its absolute bioavailability is not established and its aminoquinazoline scaffold is less structurally aligned with the query, so it only weakly opposes a low-F conclusion.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a large, lipophilic covalent inhibitor with an acrylamide warhead and aminopyrimidine core. The most mechanistically relevant human absolute-bioavailability measurement is rilzabrutinib (F <5%), a similarly large and lipophilic covalent BTK inhibitor; this outweighs less specific high-F analogues such as CC-292 and afatinib, which are smaller, more polar, or lack absolute F data. Physicochemical risks (MW 507, logD 4.46, low solubility) reinforce a low F prediction.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability data for the query molecule.",
    "No experimental solubility, permeability, or first-pass metabolism data for the query.",
    "Conflicting evidence from structurally related covalent inhibitors with low Morgan similarity scores.",
    "Absolute bioavailability for several high-F analogues (e.g., afatinib, CC-292) is not quantitatively established."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

